package com.leotv.detail;

import android.app.Activity;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.leanback.widget.*;
import androidx.leanback.widget.Presenter$ViewHolder;
import java.util.*;
import java.util.concurrent.*;
import org.json.JSONObject;

/** Original history-panel layout over actual ordinary History rows and database actions. */
final class LiulangHistory implements AutoCloseable {
    final Activity activity;final LiulangResources res;final ViewGroup root;final HorizontalGridView cards;final ArrayObjectAdapter items;
    final LiulangHeroImage hero;final ImageView poster;final TextView title,facts,description,resume,position,total;final LiulangHistoryBar progress;
    final CspHeroMetadata metadata;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();
    final Runnable changed;Object current;long generation,selected;boolean active,closed,deleteMode;
    LiulangHistory(Activity activity,LiulangResources res,ViewGroup parent,Runnable changed){this.activity=activity;this.res=res;this.changed=changed;root=(ViewGroup)res.inflate("fragment_history",parent);root.setBackgroundColor(android.graphics.Color.BLACK);res.find(root,"posterContent").setVisibility(View.VISIBLE);cards=res.find(root,"posterRecycler");items=new ArrayObjectAdapter(new Cards());cards.setAdapter(new ItemBridgeAdapter(items));cards.setHorizontalSpacing(res.dp(16));cards.setItemAnimator(null);cards.setFocusScrollStrategy(0);cards.setOnChildSelectedListener((p,v,index,id)->{if(index>=0&&index<items.size())select(items.get(index));});hero=res.find(root,"heroBg");hero.under(res.find(root,"heroBgUnder"));poster=res.find(root,"posterCardImg");title=res.find(root,"heroNameText");facts=res.find(root,"heroMetaText");description=res.find(root,"heroDescText");resume=res.find(root,"btnResume");position=res.find(root,"progressEpisode");total=res.find(root,"progressTotal");progress=res.find(root,"progressBar");metadata=new CspHeroMetadata(activity);
        resume.setOnClickListener(v->open(current));res.find(root,"deleteAll").setOnClickListener(v->NativeDialogs.choose(activity,"删除全部历史",new String[]{"取消","删除当前配置全部历史"},0,index->{if(index==1){List<Object> rows=new ArrayList<>();for(int i=0;i<items.size();i++)rows.add(items.get(i));worker.execute(()->{for(Object row:rows)SiteFeed.invoke(row,"delete");main.post(this::refresh);});}}));
    }
    static String text(Object row,String name){Object value=SiteFeed.invoke(row,name);return value==null?"":value.toString();}
    static long number(Object row,String name){Object value=SiteFeed.invoke(row,name);return value instanceof Number?((Number)value).longValue():0;}
    void refresh(){if(closed||!active)return;long token=++generation;Integer configuration=SiteFeed.configId();worker.execute(()->{try{Object result=Class.forName("com.fongmi.android.tv.bean.History",true,activity.getClassLoader()).getMethod("get").invoke(null);if(!(result instanceof List))return;List<?> rows=new ArrayList<>((List<?>)result);main.post(()->{if(closed||!active||token!=generation||!Objects.equals(configuration,SiteFeed.configId()))return;items.setItems(rows,null);res.find(root,"deleteAllBox").setVisibility(rows.isEmpty()?View.GONE:View.VISIBLE);if(!rows.isEmpty())select(rows.get(Math.min(Math.max(0,cards.getSelectedPosition()),rows.size()-1)));else{current=null;title.setText("暂无播放记录");title.setVisibility(View.VISIBLE);resume.setVisibility(View.GONE);hero.clear();}changed.run();});}catch(ReflectiveOperationException failure){main.post(()->{if(closed||!active||token!=generation)return;title.setText("播放记录暂时不可用");title.setVisibility(View.VISIBLE);android.util.Log.w("LeotvLiulang","History data unavailable",failure);});}});}
    void select(Object value){if(value==null||closed)return;current=value;long token=++selected;metadata.cancel();title.setText(text(value,"getVodName"));title.setVisibility(View.VISIBLE);facts.setText(text(value,"getSiteName"));facts.setVisibility(View.VISIBLE);description.setText(text(value,"getVodRemarks"));description.setVisibility(View.VISIBLE);resume.setVisibility(View.VISIBLE);position.setText(text(value,"getVodRemarks"));long pos=number(value,"getPosition"),duration=number(value,"getDuration");total.setText(time(pos)+" / "+time(duration));progress.progress(pos,duration);res.find(root,"progressGroup").setVisibility(duration>0?View.VISIBLE:View.GONE);res.find(root,"posterCard").setVisibility(View.VISIBLE);NativeCspUi.homeImage(poster,text(value,"getVodName"),text(value,"getVodPic"));hero.clear();try{JSONObject item=new JSONObject().put("vod_id",text(value,"getVodId")).put("vod_name",text(value,"getVodName")).put("vod_pic",text(value,"getVodPic"));main.postDelayed(()->{if(token!=selected||closed||!active)return;metadata.load(text(value,"getSiteKey"),Collections.singletonList(item),(a,b)->{if(closed||!active||token!=selected||b.isEmpty()||b.get(0)==null)return;MobileDetailMetadata.Result result=b.get(0);if(!result.facts.isEmpty())facts.setText(result.facts);if(!result.overview.isEmpty())description.setText(result.overview);if(!result.backdropPaths.isEmpty()){res.find(root,"posterCard").setVisibility(View.GONE);hero.setVisibility(View.VISIBLE);res.find(root,"maskLeft").setVisibility(View.VISIBLE);res.find(root,"maskBottom").setVisibility(View.VISIBLE);hero.load(result.backdropPaths.get(0),false,null);}});},200);}catch(org.json.JSONException ignored){}}
    static String time(long millis){long seconds=Math.max(0,millis/1000);return String.format(java.util.Locale.ROOT,"%d:%02d",seconds/60,seconds%60);}
    void open(Object row){if(row!=null)NativeRouting.openHistory(activity,text(row,"getSiteKey"),text(row,"getVodId"),text(row,"getVodName"),text(row,"getVodPic"),text(row,"getVodRemarks"));}
    boolean focusFirst(){if(items.size()==0)return false;LiulangEpisodes.focus(cards,Math.max(0,cards.getSelectedPosition()));return true;}
    void sync(){}boolean resetDelete(){if(!deleteMode)return false;deleteMode=false;items.notifyArrayItemRangeChanged(0,items.size());return true;}
    boolean key(KeyEvent event){int key=event.getKeyCode();View focused=activity.getCurrentFocus();if(key==KeyEvent.KEYCODE_DPAD_UP&&NativeCspUi.descendant(focused,cards)){if(event.getAction()==KeyEvent.ACTION_DOWN)resume.requestFocus();return true;}if(key==KeyEvent.KEYCODE_DPAD_DOWN&&focused==resume){if(event.getAction()==KeyEvent.ACTION_DOWN)focusFirst();return true;}return false;}
    void active(boolean value){active=value;if(!value){generation++;selected++;metadata.cancel();hero.active(false);main.removeCallbacksAndMessages(null);}else refresh();}
    @Override public void close(){if(closed)return;closed=true;active(false);metadata.close();hero.close();NativeCspUi.releaseHomeImage(poster);worker.shutdownNow();}
    final class Cards extends Presenter{
        @Override public Presenter$ViewHolder onCreateViewHolder(ViewGroup parent){View card=res.inflate("adapter_history_poster",parent);card.setLayoutParams(new ViewGroup.LayoutParams(res.dp(120),-2));card.setOnFocusChangeListener((v,focused)->{v.animate().cancel();v.animate().scaleX(focused?1.08f:1).scaleY(focused?1.08f:1).setDuration(150).start();});return new Presenter$ViewHolder(card);}
        @Override public void onBindViewHolder(Presenter$ViewHolder holder,Object row){TextView name=res.find(holder.view,"name");if(name!=null)name.setText(text(row,"getVodName"));ImageView image=res.find(holder.view,"image");if(image!=null)NativeCspUi.homeImage(image,text(row,"getVodName"),text(row,"getVodPic"));holder.view.setOnClickListener(v->open(row));holder.view.setOnLongClickListener(v->{NativeDialogs.choose(activity,text(row,"getVodName"),new String[]{"查看详情","删除此记录"},0,index->{if(index==0)open(row);else worker.execute(()->{SiteFeed.invoke(row,"delete");main.post(LiulangHistory.this::refresh);});});return true;});}
        @Override public void onUnbindViewHolder(Presenter$ViewHolder holder){holder.view.setOnClickListener(null);holder.view.setOnLongClickListener(null);ImageView image=res.find(holder.view,"image");if(image!=null)NativeCspUi.releaseHomeImage(image);}}
}
